+    };
+
+  nullableDelayedPackage =
+    description:
+    lib.mkOption {
+      inherit description;
+      type = lib.types.nullOr (lib.types.functionTo lib.types.pathInStore);
+      example = pkgs: pkgs.writeShellScript "echo 'Hi!'";
+      default = null;
+    };
