+          readOnly = true;
+          default = name;
+        };
+
+        get = nullableDelayedPackage ''
+          Given $1=gen_name and $2=file_name, the script retrieves the
+          respective secret to $out.
+        '';
+
+        set = delayedPackage ''
+          Given $1=gen_name and $2=file_name, the script retrieves the
+          respective secret from $in and stores it in the appropriate location.
+        '';
+
+        exists = delayedPackage ''
