+          type = safeName;
+          readOnly = true;
+          default = name;
+          defaultText = "Name of the generator";
+        };
+
+        prompts = lib.mkOption {
+          description = ''
+            A list of prompts this generator will have at its disposal.
+          '';
+          type = lib.types.listOf safeName;
