+  promptBackendModule = lib.types.submodule (
+    { name, ... }:
+    {
+      options = {
+        name = lib.mkOption {
+          description = "The name of the backend.";
+          type = lib.types.str;
+          readOnly = true;
+          default = name;
+        };
+
+        script = delayedPackage ''
+          Given $1=prompt_type and $2=prompt_text, the script runs the prompt
